CREATE TABLE public.meta_connector_settings (singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton), account_id text NOT NULL, page_id text NOT NULL); GRANT SELECT ON public.meta_connector_settings TO authenticated; GRANT ALL ON public.meta_connector_settings TO service_role; ALTER TABLE public.meta_connector_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY meta_connector_settings_read ON public.meta_connector_settings FOR SELECT TO authenticated USING (public.user_has_permission(auth.uid(), 'comm_meta_connector_campaigns', 'can_read'));